import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"大壯","description":"高島易斷 - 大壯","frontmatter":{"title":"大壯","description":"高島易斷 - 大壯"},"headers":[],"relativePath":"classics/takashima/034.md","filePath":"classics/takashima/034.md"}'),i={name:"classics/takashima/034.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="大壯" tabindex="-1">大壯 <a class="header-anchor" href="#大壯" aria-label="Permalink to “大壯”">​</a></h1><h2 id="大壯-1" tabindex="-1">大壯 <a class="header-anchor" href="#大壯-1" aria-label="Permalink to “大壯”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>大壯：利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>陽為大，陽長至四，堅實而壯，故曰《大壯》。三陽為《泰》，至四而稱壯，壯而曰大，壯之過也。《乾》曰“元亨利貞”，《震》曰“亨”，《大壯》不曰元亨，獨曰“利貞”，而六爻又多戒辭，恐其失正而動，動必得咎，是知《大壯》非《易》之所貴也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>雷在天上，大壯，君子以非禮弗履。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>大象《震》雷，發於《乾》天，勢力強壯，故名曰《大壯》。夫《隨》、《復》、《豫》、《大壯》四卦，皆得《震》體，故皆取象於雷。《隨》雷入澤中，陽勢漸收，是謂秋雷；《復》雷入地中，陽勢已微，是謂冬雷；《豫》“雷出地奮”，陽勢方盛，是謂春雷；《大壯》曰“雷在天上”，陽勢健盛，是謂當令之夏雷也。君子則之，謂雷之發聲，必以其時，不時則為災；君子之踐履，必由於禮，非禮則有悔。《乾》為行，《震》為足，有《履》之象。《乾》之《象》曰，“君子以自強不息”，《震》之《象》曰，“君子以恐懼修省”，合而言之，君子因欲自強，惟以非禮而履者，為可懼耳，即夫子所謂“非禮勿視，非禮勿聽，非禮勿言，非禮勿動”之旨也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問戰徵：軍勢強盛，有疾雷不及掩耳之勢；但兵驕必敗，所當深戒。</p><p>○　問營商：雷在天上，是貨價高標之象，得價而售，不可過。</p><p>○　問功名：雷聲遠震，必得成名。</p><p>○　問家宅：防有火災，宜禱。</p><p>○　問疾病：《震》為雷，亦為足，防有足疾，不能行也。</p><p>○　問婚姻：《震》為《乾》之長子，《巽》為《坤》之長女，是天合也，吉。</p><p>○　問失物：雷一過而無形，恐此物不能復得。</p><p>○　問六甲：生男。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初居《大壯》之始，在下卦之下，在下而動，故曰“壯於趾”；《震》為徵，故曰“徵”；邁徵而往，有急起直追之勢，無“視履考祥”之念，是以兇也，故曰“徵兇。”“有孚”，《象傳》曰“其孚窮也”，謂初雖與四應，初既窮其所往，四又隔遠，無能為力也，故曰“其孚窮也”。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問戰徵：“壯於趾，徵兇”，為孤軍深入者戒也，有勇無謀，是以兇也。</p><p>○　問營商：貨財販運，有不脛而走、不翼而飛之妙；然不度銷路，而貿然而往，何能獲利？故兇。</p><p>○　問功名：初本在下，曰“趾”，則動亦在下，功名必卑。</p><p>○　問家宅：“趾”，止也，此宅宜安止，不宜遷動，動則有兇。</p><p>○　問婚姻：防女有足疾。“徵兇，有孚”，謂雖有聘約，“其孚窮也”。</p><p>○　問失物：此物已被足所踐踏而壞。</p><p>○　問六甲：生男。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某來，請佔事業之成否，筮得《大壯》之《恆》。</p><p>斷曰：初爻居《乾》之始，在內卦之下，是必發事謀始，機會未至，而足先欲動者，故有壯趾之象。足下佔事業，而得《大壯》初爻，知足下志在速成，當謀劃未詳，經驗未定，而貿然前進，不特無利，且有兇也，故曰“壯於趾，徵兇，有孚”。“壯於趾，徵兇”者，謂輕舉而取失敗；“有孚”者，謂徒有此約信也。此事須待時而動，緩圖則吉，今乃倉猝求成，是以兇也。友人不用此佔，急遽興業，遂致失策而傾家；後有人以資金三分之一，繼承其業，反得大利。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>全卦諸爻，皆失於過剛，惟二爻為得中，中者不偏之謂也。二與五應，無牴觸之失，是以無過不及，而進退適宜，故不言“壯”，不言“正”，直曰“貞吉”，蓋即以《彖》之“利貞”歸之，而著其吉也。《易》道雖貴扶陽抑陰，然陽剛過盛，亦失其中，故必抑其過剛，以就其中，中則正，正則吉也。《象傳》曰“以中也”，以九二當下卦之中，剛而能柔，所處得中也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問戰徵：以中營得力，故能獲勝，吉。</p><p>○　問營商：以貨價適宜，得其時中，可獲利也。</p><p>○　問功名：恰好中式，吉。</p><p>○　問婚姻：雀屏中選，吉。</p><p>○　問家宅：此宅坐西朝東，地位適中，大吉。</p><p>○　問疾病：病在中焦，宜用潛陽滋陰之劑，自得痊癒。吉。</p><p>○　問訟事：得中人調劑，即息。</p><p>○　問六甲：生男。</p><p>○　問行人：已在中途，即可歸也。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某會社社長，來請佔氣運，筮得《大壯》之《豐》。</p><p>斷曰：此卦四陽在下，二陰在上，陽大陰小，剛浸而長，故曰《大壯》。足下佔會社而得二爻，可見社中資金充裕，足以有為。足下身任社長，所當以柔濟剛，以靜制動，從容辦事，不期速效，謙和有禮，進退悉中，自能徐徐獲益，吉無不利也。後二年，至四爻，四為《大壯》之主，可得大利。後果如所佔。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“羝羊”，牡羊也。三至五體《兌》，為羊，故取象於羊；卦體純剛，故曰“羝羊”，以喻剛陽之盛也。三當內卦之終，逼近外卦，《乾》剛《震》動，壯象將成。小人處此，必將恃其壯而壯焉，是謂“用壯”；君子有其壯，而不敢自居其壯，一若未嘗有壯也，故曰“用罔”。“罔”，無也，京房曰，“壯一也，小人用之”，君子有而不用是也。三以陽處陽，重剛不中，雖貞亦危，故曰“貞厲”。君子因其厲而益加強焉，朝乾夕惕，時以非禮自防，不敢或逞其壯，所謂以有若無也。九四體《震》，為竹葦，故曰“藩”；藩所以閒羊，四在前，三觸之，故曰“羝羊觸藩”，象小人之用壯也。“羸”，鄭虞作累，為拘累纏繞；“羸其角”，角，羊角，謂羊觸藩，其角為藩所拘累，而不能出也，以喻用壯之危。“小人用壯”，當知所返矣；“君子用罔”，斯可免危矣。《象》曰“小人用壯”，小人第知有壯；“君子罔也”，去一“用”字，益見君子之不用，所貴斂之以無也。一說：罔，法網也，君子知壯之為厲，凜凜然以刑網為戒，即君子懷刑之意。亦通。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問戰徵：善戰者審機察敵，不敢妄動；恃勇者逞強戰鬥，孤軍直入，致陷險地而不能出，是以兇也。</p><p>○　問營商：自恃資財之富，任意壟斷，一至貨物毀折，無地銷售，必遭大損。善賈者當無是慮。</p><p>○　問功名：魯莽者必敗，謙退者成名。</p><p>○　問家宅：此宅地位既高，建屋宜低，屋高恐有震陷之災。</p><p>○　問疾病：病由血氣過剛，藥宜調血下氣。</p><p>○　問訟事：以忍氣受屈，息訟為宜，若健訟不休，訟則“終兇”。</p><p>○　問婚姻：兩姓或一貧一富，若富者恃富凌貧，以致夫妻反目，兇。</p><p>○　問六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某來，請佔商業盛衰，筮得《大壯》之《歸妹》。</p><p>斷曰：此卦內卦《乾》父，外卦《震》子，是父主謀於內，子幹事於外，父子協力，以創興家業，財力旺壯，故曰《大壯》。足下佔商業，而得三爻，以陽居陽，爻位皆剛，若徑情直往，其壯強之勢，幾可壓倒同業，然過剛必折，恐反為同業所軋，必遭窘辱，如羊之觸藩而不能出也。善賈者堅貞自處，不敢挾富而生驕，亦不敢恃才而自侈，雖有其壯，而不用其壯，斯得處壯之方，即得生財之道也。足下其熟審之！後友人乘壯用事，果為同業所擠，損失數萬金。</p><p>明治二十七年五月中旬，我國駐英國公使某罹病，友人某憂之，請餘一佔。筮得《大壯》之《歸妹》。</p><p>斷曰：此卦陽長之卦，三爻又以陽居陽，《震》為木，木屬肝，是必肝陽過盛，脾陰受克之症。某公使素體壯健，醫者因其壯而誤為實火，一味瀉肝息陽，而元氣愈虛，肝陽愈燥，病至不可藥救，是謂用壯之誤也。善醫者當以育陰潛陽治之，所謂“用罔也”。至論爻象，三爻變為《歸妹》，歸者，歸也，至四爻變《泰》，則病可療。今當五月中旬，必過此一月後，可望平愈，然恐不及也。後某氏之病，果以翌月四日遂亡。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>九四出《乾》入《震》，為《震》之始，以陽居陰，不極其剛，故得吉而悔亡也。三之有藩，藩在四也，四前二陰，則藩決矣。“輹”，車軸縛也，《坤》為大輿，《震》上二陰得《坤》氣，故亦曰“大輿”。輹壯則輿強，言行遠而無礙也。率此以往，壯而不見其壯，悔何有焉？《象傳》曰“藩決不羸，尚往也”，謂壯得其貞，乃可許其前往也。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問戰徵：前途城垣已破，車馳馬逐，長征可無阻也。</p><p>○　問功名：九四互《乾》，辰在戌，上值奎壁，壁主文昌，所以崇文德也，功名必顯。王良五星在壁北，主車馬，大輿之象；雷電六星亦相近，主興雷，即《震》雷之象。</p><p>○　問營商：可許滿載而歸，吉。</p><p>○　問家宅：此宅當車馬往來之地，宅前藩籬破落，急宜修整。</p><p>○　問疾病：人以髮膚為藩衛，以心神為輿馬，髮膚破裂，心神搖盪，病不久矣。</p><p>○　問婚姻：“車脫輹，夫妻反目”，非佳偶也。不吉。</p><p>○　問六甲：九四為《震》之始，《震》一索得男，為長子也。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二十七年九月，大本營之進廣島也，大元帥陛下，將發親征。恭筮一卦，得《大壯》之《泰》。</p><p>斷曰：此卦四陽連進，上決二陰，其勢盛大，故曰《大壯》。今我興徵清之師，彼嚴兵固壁，尚不能當，況其藩衛已決，何能御我乎！恍如騁大車於坦途，可預決也。爻象如此，其吉可知，因呈此斷於某貴顯。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>上卦互《兌》，《兌》為羊，五正是羊。“喪”，亡也；“易”音亦，陸作場，謂疆場也，易場古通字。《乾》為郊，郊外謂之牧，五當《乾》郊外疆場之地，畜牧之所也。畜牧有藩，防其逸也。卦以《震》之下畫為藩，三觸之，四則藩決矣，五則羊逸，羊逸於易，所謂“大道多岐而亡羊”，故曰“喪羊於易”。五居《震》卦之中，偶畫為陰，易，為曠郊陰地，陰爻而入陰地，不見其壯，故象為“喪羊”。且羊性剛滷，喜觸，無羊則無觸，無觸則無用壯之悔，故曰“無悔”。《旅》上九曰“喪牛於易”，“易”亦作場。《旅》宜柔，喪其柔，是以“有兇”也；《大壯》惡剛，喪其剛，是以“無悔”也。《象傳》曰：“位不當”，謂“無悔”在得中，不在當位，猶九二之“貞吉”，《象》曰“以中”，亦不在位也。總之，《大壯》一卦，《彖》所稱“利貞”，以事理言，不以爻位言也，明矣。“易”字，鄭謂交易，《本義》讀作以智切，音異，謂容易也。義各有取。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問戰徵：三爻曰“羝羊觸藩”，有攻擊之象，“喪羊”則無觸，而戰事可平。</p><p>○　問營商：“易”，鄭謂交易，有經商之義；“喪”，亡也，恐有小失，然無大悔。</p><p>○　問功名：以得為吉，以喪為兇，亡羊補牢，未為晚也。晚年可望。</p><p>○　問家宅：此宅在郊外空曠之處，於牧畜不利。</p><p>○　問疾病：“喪”，兇象，不吉。</p><p>○　問婚姻：牽羊擔酒，婚禮也，無羊，婚禮不成。</p><p>○　問六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>友人某來曰：頃日有一種貨物，可居奇獲利，請佔一卦，以定盈虧。筮得《大壯》之《夬》。</p><p>斷曰：此卦四陽在下，其勢甚壯，故名《大壯》。今佔得第五爻，五處外卦之中，二畫為陰，壯勢已失，爻曰“喪羊”，是必有喪而無得。友人曰：臺灣之事，購入軍中所需食料品物，他日與清開戰，實一大買賣也。後聞得和平之信，頓為驚愕，遂遭大耗，三年之後，猶不得償全額雲。</p><p>明治二十七年十一月二十日，某貴顯來訪曰：目下旅順口形勢如何？試為一筮。筮得《大壯》之《夬》。</p><p>斷曰：以我國佔旅順，旅順屬清，是外國也。今佔得五爻，五居外卦之中，當以我國為內卦，旅順為外卦。“喪”者清國，得者我國也。爻辭“喪羊於易”，“易”，謂容易也。蓋不須力戰而得之也，數日內，當必有捷報到來。後數日，旅順陷，果如此佔。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上處外卦之終，與三相應，上之羊，猶是三之羊，上之觸，猶是三之觸。三雖羸角，乘剛而動，力能決藩，亦可進也，即不能進，尚可退也；至上勢衰位極，爻處重陰，後路既斷，前路又窮，將安歸乎？不曰“不能進”，而曰“不能遂”，言終不能遂其壯往之願也。視三之羸角，困益甚焉，利何有也！因退遂之不能，而惕之以“艱”，毖後懲前，“非禮弗履”，亦何難轉咎為吉哉！《象傳》所謂“不祥也”，言其不能“視履考祥”，故至退遂之兩窮也。所謂“咎不長也”，言能知其所艱，則謹慎自守，壯終於此，咎亦終於此耳。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問戰徵：六處爻之窮，如追窮寇也，恃勝深入，及為敗軍所困，進退無路，兇道也。</p><p>○　問營商：是一意居奇，積貨不售，至時過價賤，只要保本，而亦不得，其困甚矣。</p><p>○　問功名：在上爻有位高而危之象，若戀戀不退，一旦禍及，欲退不能，悔已晚矣。</p><p>○　問家宅：上爻居《震》之極，《震》為響，宅中必有響；《震》又為木，木動克土，恐有土精出現，土精為羊。其宅不利，所當艱難自守，至之卦為《晉》，《晉》曰“賜馬蕃庶”，則可轉咎為吉。</p><p>○　問婚姻：未及詳探，一時已定，茲要改悔，必不能也。現當知苦困守，久後必佳。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>一日過訪杉君，閒談移晷，杉君謂餘曰；昨夕有偷兒入我倉庫，竊取物品若干，中有勳章禮服，是貴重之品也，未審可復得乎？子試筮之。筮得《大壯》之《晉》。</p><p>斷曰：上為爻之極，賊竊得勳章禮服，貴重之品，在賊既不能轉售，又不能自用，賊無所利，計亦窮矣。爻曰：“羝羊觸藩”，羊性剛滷，以喻賊之鹵莽也。“觸藩”者賊，或將以此貴物，置之於鄰近藩籬間乎？君請搜尋之。後果於鄰邸牆垣上尋得之。杉君大為贊稱。</p>',103)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
